// MoonProof data layer: every value travels with its origin and state.
// Static NASA-derived products come from web/data/ (loaded with web/lab/ modules, not copied);
// the API uses the shared deployment-aware URL resolver; absence is shown, never hidden.
// Source of truth: this .ts file. data.js is generated by `npm --prefix web run build:ts`.
// The three imports below are untyped JS modules (no declaration files): their bindings are `any`.
// @ts-ignore TS7016
import { SiteSeries, HOUR_MS } from "../../lab/data.js";
// @ts-ignore TS7016
import { TerrainGrid } from "../../lab/terrain.js";
// @ts-ignore TS7016
import { apiURL } from "../../api-base.js";
// @ts-ignore TS7016
export { apiBase } from "../../api-base.js";

export type Seal = "VAL" | "PRE" | "EST" | "SIM" | "N/D" | "FALHA";

/** One of the sites of web/data/sites.json (`n` = 1-based position in the file). */
export interface Site {
  id: string; n: number; name?: string; lat?: number; lon?: number; source?: string; series: string;
  metrics?: Record<string, number | null | undefined>; pgda_sun_pct?: number | null;
  [key: string]: unknown;
}
export interface SitesDoc {
  status: string; note: string; window: unknown; generated: string; features: unknown[]; sites: Site[];
}
/** Window summary of a stored hourly series (SiteSeries.window). */
export interface SeriesWindow {
  status: string; sunPct: number | null; earthPct: number | null; longestDarkH: number | null; longestBlackoutH: number | null; maxSunElDeg: number | null;
  [key: string]: unknown;
}
/** The stored hourly series of a site (web/lab/data.js SiteSeries), as far as the screens use it. */
export interface SiteSeriesLike {
  start: number; count: number; sunMargin: ArrayLike<number>; earthMargin: ArrayLike<number>;
  meta: { series: { sha256?: string; step_seconds?: number }; site?: { observer_height_m?: number } };
  window(t0: number, hours: number): SeriesWindow;
}
export interface Sourced<T = unknown> {
  readonly value: T | null; readonly unit: string; readonly status: string | undefined; readonly seal: Seal;
  readonly source: string; readonly detail: Readonly<Record<string, unknown>>;
}
export type ApiResult<T = unknown> =
  | { ok: true; data: T; status: string | null; offline?: undefined; error?: undefined }
  | { ok: false; offline: boolean; error: string; httpStatus?: number; code?: string | null };

export const DATA_BASE: string = new URL("../../data/", import.meta.url).href;
export const SEALS: Seal[] = ["VAL", "PRE", "EST", "SIM", "N/D", "FALHA"];

/**
 * Map an origin state to a seal. VAL is returned ONLY for the exact state "VALIDATED".
 * PRELIMINARY_* → PRE, SYNTHETIC → SIM, UNVERIFIED_INPUTS → EST, NO_SERIES_DATA/missing → N/D, ERROR → FALHA.
 */
export function sealFor(status?: string | null): Seal {
  const s = String(status || "").toUpperCase();
  if (s === "VALIDATED") return "VAL";
  if (s.startsWith("PRELIMINARY")) return "PRE";
  if (s === "SYNTHETIC" || s.includes("SYNTHETIC") || s === "SIMULATION") return "SIM";
  if (s === "UNVERIFIED_INPUTS" || s === "ESTIMATE") return "EST";
  if (s === "ERROR" || s === "FAILED") return "FALHA";
  return "N/D";
}

/**
 * A value with provenance. Missing/non-finite value → seal N/D (never 0).
 * { value, unit, status, seal, source, detail }  — detail is free text for the Proof layer.
 */
export function sourced<T = unknown>(value: T | null | undefined, { unit = "", status, source = "", detail = {} }: { unit?: string; status?: string; source?: string; detail?: Record<string, unknown> } = {}): Sourced<T> {
  const missing = value == null || (typeof value === "number" && !Number.isFinite(value));
  return Object.freeze({ value: missing ? null : value as T, unit, status: missing ? (status === "ERROR" ? "ERROR" : "NO_DATA") : status,
    seal: missing ? (status === "ERROR" ? "FALHA" : "N/D") : sealFor(status), source, detail });
}

let sitesP: Promise<SitesDoc> | null = null;
/** The five real sites of web/data/sites.json, numbered 1..n in file order. */
export function loadSites(): Promise<SitesDoc> {
  return sitesP ||= fetch(DATA_BASE + "sites.json").then(r => { if (!r.ok) throw new Error("sites.json " + r.status); return r.json(); })
    .then(doc => ({ status: doc.science_status, note: doc.note, window: doc.series_window, generated: doc.generated_utc, features: doc.features || [],
      sites: (doc.sites as Site[]).map((s, i) => ({ ...s, n: i + 1 })) }));
}

/** Long-term metric of a site as a sourced value (from sites.json metrics). */
export function siteMetric(doc: Pick<SitesDoc, "status" | "window" | "generated">, site: Site | null | undefined, key: string, unit: string): Sourced<number> {
  return sourced(site?.metrics?.[key], { unit, status: doc.status,
    source: "web/data/sites.json · metrics." + key, detail: { window: doc.window, generated: doc.generated } });
}

/** Tolerance of the science review against NASA PGDA (docs/SCIENCE_REVIEW_ONBOARD_BS061.md, section 2.2). */
export const PGDA_SUN_TOLERANCE_PP = 5;
/**
 * null, or why the sunlight figures of a site are to be read as an upper bound: our series shows more
 * sunlight than the NASA PGDA average map by more than the tolerance. Decided from sites.json alone
 * (metrics.mean_solar_disc_visible_pct against pgda_sun_pct), never from a site id.
 */
export function sunCaveat(site: Site | null | undefined): Readonly<{ kind: "SUN_UPPER_BOUND"; ours: number; pgda: number; diff: number }> | null {
  const ours = site?.metrics?.mean_solar_disc_visible_pct, pgda = site?.pgda_sun_pct;
  if (typeof ours !== "number" || typeof pgda !== "number" || !Number.isFinite(ours) || !Number.isFinite(pgda) || ours - pgda <= PGDA_SUN_TOLERANCE_PP) return null;
  return Object.freeze({ kind: "SUN_UPPER_BOUND" as const, ours, pgda, diff: ours - pgda });
}

const seriesCache = new Map<string, Promise<SiteSeriesLike>>();
export function loadSeries(site: Pick<Site, "id" | "series">): Promise<SiteSeriesLike> {
  if (!seriesCache.has(site.id)) seriesCache.set(site.id, SiteSeries.load(DATA_BASE + site.series));
  return seriesCache.get(site.id) as Promise<SiteSeriesLike>;
}

/** Window metrics for [startIso, +hours) from the stored hourly series, each value sourced. */
export async function windowMetrics(doc: Pick<SitesDoc, "status">, site: Pick<Site, "id" | "series">, startIso: string | null | undefined, hours: number) {
  const series = await loadSeries(site);
  const t0 = startIso ? Date.parse(startIso) : series.start;
  const w = series.window(t0, hours);
  const st = w.status === "COMPUTED" ? doc.status : "NO_SERIES_DATA";
  const base = { status: st, source: "web/data/" + site.series + ".bin", detail: { sha256: series.meta.series.sha256, start: new Date(t0).toISOString(), hours, step: "1 h" } };
  return { raw: w, series, t0,
    sunPct: sourced(w.sunPct, { ...base, unit: "%" }), earthPct: sourced(w.earthPct, { ...base, unit: "%" }),
    longestDarkH: sourced(w.longestDarkH, { ...base, unit: "h" }), longestBlackoutH: sourced(w.longestBlackoutH, { ...base, unit: "h" }),
    maxSunElDeg: sourced(w.maxSunElDeg, { ...base, unit: "°" }) };
}

/** Per-day sunlit fraction (0..1) over the window, for the "Why" bar. */
export function dailySun(series: Pick<SiteSeriesLike, "start" | "count" | "sunMargin">, t0: number, hours: number): (number | null)[] {
  const out: (number | null)[] = []; const i0 = Math.ceil((t0 - series.start) / HOUR_MS);
  for (let d = 0; d * 24 < hours; d++) {
    let on = 0, n = 0;
    for (let h = d * 24; h < Math.min(hours, d * 24 + 24); h++) { const i = i0 + h; if (i < 0 || i >= series.count) continue; n++; if (series.sunMargin[i] >= 0) on++; }
    out.push(n ? on / n : null);
  }
  return out;
}

let gridP: Promise<unknown> | null = null;
export function loadRegion(): Promise<unknown> { return gridP ||= TerrainGrid.load(DATA_BASE + "region/south_pole_400m"); }

/**
 * Call the API. Resolves {ok:true, data, status} or {ok:false, offline, httpStatus, code, error}. Never throws.
 * status is the payload's own science state when present (science_status / status / state).
 */
export async function api<T = unknown>(path: string, { method = "GET", body, timeoutMs = 8000, as = "json" }: { method?: string; body?: unknown; timeoutMs?: number; as?: "json" | "text" } = {}): Promise<ApiResult<T>> {
  const ctl = new AbortController(); const tm = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    const r = await fetch(apiURL(path), { method, signal: ctl.signal,
      headers: body ? { "content-type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined });
    if (!r.ok) {
      const payload = await r.json().catch(() => null) as { code?: unknown } | null;
      const code = typeof payload?.code === "string" ? payload.code : null;
      return { ok: false, offline: r.status >= 500, httpStatus: r.status, code, error: "HTTP " + r.status + (code ? " · " + code : "") };
    }
    if (as === "text") {
      if (!/^text\/html(?:;|$)/i.test(r.headers.get("content-type") || "")) return { ok: false, offline: false, httpStatus: r.status, error: "INVALID_REPORT_TYPE" };
      return { ok: true, data: await r.text() as T, status: null };
    }
    const data = await r.json();
    return { ok: true, data, status: data?.science_status || data?.status || data?.state || null };
  } catch (e) { return { ok: false, offline: true, error: String((e as { message?: unknown } | null)?.message || e) }; }
  finally { clearTimeout(tm); }
}
/** true when /readyz answers. Screens show "offline · precomputed" otherwise. */
export async function apiOnline(): Promise<boolean> { return (await api("/readyz", { timeoutMs: 3000 })).ok; }
